const row = $('Pengaturan').first().json;
const bersih = s => String(s || '').replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{200D}]/gu, '').replace(/\s+/g, ' ').trim();
const daftar = [];
function tambah(tipe, judul, isi) {
  const j = bersih(judul);
  const b = bersih(isi);
  if (!j && !b) return;
  daftar.push({ tipe: tipe, judul: j, isi: b });
}
tambah('cover', row.cover_title, row.cover_subtitle);
for (let i = 1; i <= 10; i++) {
  const n = String(i).padStart(2, '0');
  tambah('isi', row['slide_' + n + '_title'], row['slide_' + n + '_body']);
}
if (daftar.length < 2) {
  throw new Error('Baris ' + row.id + ' punya kurang dari 2 slide');
}
const total = daftar.length;
return daftar.map((d, i) => ({ json: { row_id: row.id, no: i + 1, total: total, tipe: (i === total - 1 ? 'cover' : d.tipe), judul: d.judul, isi: d.isi } }));

const rowId = $('Pengaturan').first().json.id;
const uploads = $input.first().json.uploads || [];
const urls = uploads.map(u => (u.data && u.data.url) || u.url).filter(Boolean);
if (!urls.length) {
  throw new Error('Tidak ada URL gambar yang berhasil diunggah untuk baris ' + rowId);
}
return [{ json: { id: rowId, image_urls: urls.join(', '), urls: urls, jumlah_gambar: urls.length } }];

