const cfg0 = $('Pengaturan').first().json;
const cfg = Object.assign({}, cfg0);
try {
  const e = $('Akun Ebooks').first().json;
  if (e && e.ig_user_id) {
    cfg.connected_account_id = e.connected_account_id;
    cfg.ig_user_id = e.ig_user_id;
    cfg.ig_username = e.ig_username;
  }
} catch (err) {}
const urls = ($('Susun Daftar URL').first().json.urls || []).slice(0, 10);
if (urls.length < 2) {
  throw new Error('Carousel Instagram butuh minimal 2 gambar, yang tersedia ' + urls.length);
}
let n = 0;
const caption = String(cfg.caption || '')
  .split(/(\s+)/)
  .filter(w => {
    if (w.charAt(0) === '#') { n += 1; return n <= 30; }
    return true;
  })
  .join('')
  .slice(0, 2200);
return [{ json: { id: cfg.id, connected_account_id: cfg.connected_account_id, ig_user_id: cfg.ig_user_id, ig_username: cfg.ig_username, caption: caption, child_image_urls: urls } }];

const r = $input.first().json || {};
const cfg = $('Siapkan Data Post').first().json;
let id = '';
let err = '';
try {
  const raw = typeof r.data === 'string' ? r.data : '';
  const line = raw.split('\n').find(l => l.startsWith('data: '));
  if (!line) throw new Error(String(r.error ? JSON.stringify(r.error) : raw || JSON.stringify(r)));
  const msg = JSON.parse(line.slice(6));
  const o = JSON.parse(msg.result.content[0].text);
  const res = (o.data && o.data.results && o.data.results[0]) || {};
  const resp = res.response || {};
  const d = resp.data || {};
  id = d.id || d.creation_id || (d.data && d.data.id) || (d.response_data && (d.response_data.id || d.response_data.creation_id)) || '';
  if (!(resp.successful === true && id)) throw new Error(String(res.error || resp.error || o.error || JSON.stringify(d)));
} catch (e) {
  err = String(e.message || e).replace(/[<>_*]/g, ' ').slice(0, 200);
  id = '';
}
const ok = !!id;
return [{ json: { ok: ok, creation_id: String(id), id: cfg.id, ig_user_id: cfg.ig_user_id, connected_account_id: cfg.connected_account_id, ig_username: cfg.ig_username, error: err } }];

