const rows = $input.all().map(i => i.json);
const now = Date.now();
let best = null;
let bestT = 0;
for (const r of rows) {
  const m = /^CRS-(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})$/.exec(String(r.id || ''));
  if (!m) continue;
  const t = Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 7, +m[5], +m[6]);
  const umurMenit = (now - t) / 60000;
  if (umurMenit < -10 || umurMenit > 120) continue;
  if (t > bestT) { bestT = t; best = r; }
}
return best ? [{ json: best }] : [];

