const r = $input.first().json || {};
let out = { successful: false, data: { id: '' }, error: '' };
try {
  const raw = typeof r.data === 'string' ? r.data : '';
  const line = raw.split('\n').find(l => l.startsWith('data: '));
  if (!line) throw new Error(String(r.error ? JSON.stringify(r.error) : raw || JSON.stringify(r)));
  const msg = JSON.parse(line.slice(6));
  const o = JSON.parse(msg.result.content[0].text);
  const res = (o.data && o.data.results && o.data.results[0]) || {};
  const resp = res.response || {};
  const d = resp.data || {};
  const id = d.id || (d.data && d.data.id) || (d.response_data && d.response_data.id) || '';
  if (resp.successful !== true) throw new Error(String(res.error || resp.error || o.error || JSON.stringify(d)));
  out = { successful: true, data: { id: String(id) }, error: '' };
} catch (e) {
  out.error = String(e.message || e).replace(/[<>_*]/g, ' ').slice(0, 200);
}
return [{ json: out }];
